import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// 阶段计算函数
const 计算堕落阶段 = (v) => v <= 25 ? '正常距离' : v <= 40 ? '隐秘动摇' : v <= 60 ? '被动迎合' : v <= 80 ? '情感沉迷' : '肉便器';
const 计算性欲阶段 = (v) => v <= 19 ? '平静' : v <= 39 ? '微热' : v <= 59 ? '渴望' : v <= 79 ? '饥渴' : '发情';
const 计算怀疑阶段 = (v) => v <= 30 ? '信任' : v <= 60 ? '疑虑' : v <= 90 ? '警惕' : '确信';
const 计算好感阶段 = (v) => v <= 20 ? '好感' : v <= 40 ? '暧昧' : v <= 60 ? '撩拨' : v <= 80 ? '越界' : '沉沦';

export const Schema = z.object({
  // 世界状态
  日期: z.string().prefault('待初始化'),
  星期: z.string().prefault('待初始化'),
  时间: z.string().prefault('待初始化'),
  当前地点: z.string().prefault('待初始化'),

  // 可触发事件
  事件_温泉旅行: z.string().prefault('🔒 需要堕落值30解锁'),
  事件_海边出游: z.string().prefault('🔒 需要堕落值45解锁'),
  事件_露营过夜: z.string().prefault('🔒 需要堕落值60解锁'),

  // 郑甜
  郑甜: z.object({
    堕落值: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
    堕落阶段: z.string().prefault('正常距离'),
    性欲值: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
    性欲阶段: z.string().prefault('平静'),
    当前行动: z.string().prefault('待初始化'),
    当前穿搭: z.string().prefault('待初始化'),
    内心想法: z.string().prefault('待初始化'),
    身体状况: z.string().prefault('待初始化'),
    最近性行为: z.string().prefault('待初始化'),
    堕落40触发: z.enum(['未触发', '已触发']).prefault('未触发'),
    对比做爱完成: z.enum(['否', '是']).prefault('否'),
  }).transform(data => {
    if (data.对比做爱完成 === '否') {
      data.堕落值 = _.clamp(data.堕落值, 0, 40);
    }
    data.堕落阶段 = 计算堕落阶段(data.堕落值);
    data.性欲阶段 = 计算性欲阶段(data.性欲值);
    return data;
  }),

  // 苏晚晴
  苏晚晴: z.object({
    堕落值: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
    堕落阶段: z.string().prefault('正常距离'),
    性欲值: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
    性欲阶段: z.string().prefault('平静'),
    当前行动: z.string().prefault('待初始化'),
    当前穿搭: z.string().prefault('待初始化'),
    内心想法: z.string().prefault('待初始化'),
    身体状况: z.string().prefault('待初始化'),
    最近性行为: z.string().prefault('待初始化'),
    堕落40触发: z.enum(['未触发', '已触发']).prefault('未触发'),
    对比做爱完成: z.enum(['否', '是']).prefault('否'),
  }).transform(data => {
    if (data.对比做爱完成 === '否') {
      data.堕落值 = _.clamp(data.堕落值, 0, 40);
    }
    data.堕落阶段 = 计算堕落阶段(data.堕落值);
    data.性欲阶段 = 计算性欲阶段(data.性欲值);
    return data;
  }),

  // 姜悦悦
  姜悦悦: z.object({
    好感度: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(20),
    好感阶段: z.string().prefault('好感'),
    当前行动: z.string().prefault('待初始化'),
    内心想法: z.string().prefault('待初始化'),
    当前穿搭: z.string().prefault('待初始化'),
  }).transform(data => {
    data.好感阶段 = 计算好感阶段(data.好感度);
    return data;
  }),

  // 许晴柔
  许晴柔: z.object({
    好感度: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(15),
    好感阶段: z.string().prefault('好感'),
    当前行动: z.string().prefault('待初始化'),
    内心想法: z.string().prefault('待初始化'),
    当前穿搭: z.string().prefault('待初始化'),
  }).transform(data => {
    data.好感阶段 = 计算好感阶段(data.好感度);
    return data;
  }),

  // 周彦（郑甜的男友）
  周彦: z.object({
    地点: z.string().prefault('待初始化'),
    行动: z.string().prefault('待初始化'),
    想法: z.string().prefault('待初始化'),
    认为女友在干嘛: z.string().prefault('待初始化'),
    怀疑值: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
    怀疑阶段: z.string().prefault('信任'),
    是否联系女友: z.enum(['是', '否']).prefault('否'),
  }).transform(data => {
    data.怀疑阶段 = 计算怀疑阶段(data.怀疑值);
    return data;
  }),

  // 林昭（苏晚晴的男友）
  林昭: z.object({
    地点: z.string().prefault('待初始化'),
    行动: z.string().prefault('待初始化'),
    想法: z.string().prefault('待初始化'),
    认为女友在干嘛: z.string().prefault('待初始化'),
    怀疑值: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
    怀疑阶段: z.string().prefault('信任'),
    是否联系女友: z.enum(['是', '否']).prefault('否'),
  }).transform(data => {
    data.怀疑阶段 = 计算怀疑阶段(data.怀疑值);
    return data;
  }),

}).transform(data => {
  const 最大堕落值 = Math.max(data.郑甜.堕落值, data.苏晚晴.堕落值);

  if (data.事件_温泉旅行.startsWith('🔒') && 最大堕落值 >= 30) {
    data.事件_温泉旅行 = '✅ 可触发';
  }
  if (data.事件_海边出游.startsWith('🔒') && 最大堕落值 >= 45) {
    data.事件_海边出游 = '✅ 可触发';
  }
  if (data.事件_露营过夜.startsWith('🔒') && 最大堕落值 >= 60) {
    data.事件_露营过夜 = '✅ 可触发';
  }

  return data;
});

$(() => {
  registerMvuSchema(Schema);
})

