      $('#xqr-action').text(xqrAction);
      $('#xqr-thought').text(xqrThought);
      $('#xqr-outfit').text(xqrOutfit);

      // ===== 可触发事件（根级变量，带前缀） =====
      const hotspringStatus = _.get(all_variables, 'stat_data.事件_温泉旅行', '🔒 需要堕落值30解锁');
      const beachStatus = _.get(all_variables, 'stat_data.事件_海边出游', '🔒 需要堕落值45解锁');
      const campStatus = _.get(all_variables, 'stat_data.事件_露营过夜', '🔒 需要堕落值60解锁');

      const hotspringUnlocked = hotspringStatus.includes('✅');
      const beachUnlocked = beachStatus.includes('✅');
