    async function init() {
      await waitGlobalInitialized('Mvu');
      populateCharacterData();

      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
        populateCharacterData();
      });

      // 角色卡片折叠
      $('.char-header').on('click', function() {
        $(this).toggleClass('collapsed');
        $(this).next('.char-detail').toggleClass('hidden');
      });

      $('.char-header').addClass('collapsed');
      $('.char-detail').addClass('hidden');

      // 其他角色区域折叠
      $('.others-header').on('click', function() {
        $(this).toggleClass('collapsed');
        $(this).next('.others-list').toggleClass('hidden');
      });

      $('.others-header').addClass('collapsed');
      $('.others-list').addClass('hidden');

      // 事件区域折叠
      $('.events-header').on('click', function() {
        $(this).toggleClass('collapsed');
        $(this).next('.events-list').toggleClass('hidden');
      });

      $('.events-header').addClass('collapsed');
      $('.events-list').addClass('hidden');

      // 主题切换
      $('#theme-btn').on('click', function() {
        if ($('body').hasClass('night')) {
          $('body').removeClass('night').addClass('day');
          $(this).html('☀️');
        } else {
          $('body').removeClass('day').addClass('night');
          $(this).html('🌙');
        }
      });
    }

    $(errorCatched(init));
  </script>
