  <script type="module">
    function populateCharacterData() {
      const all_variables = getAllVariables();

      // ===== 世界状态（根级变量） =====
      const worldDate = _.get(all_variables, 'stat_data.日期', '-');
      const worldWeekday = _.get(all_variables, 'stat_data.星期', '');
      const worldTime = _.get(all_variables, 'stat_data.时间', '-');
      const worldLocation = _.get(all_variables, 'stat_data.当前地点', '-');

      $('#world-datetime').text(worldDate + ' ' + worldTime);
      if (worldWeekday) $('#world-weekday').text(worldWeekday).show(); else $('#world-weekday').hide();
      $('#world-location').text(worldLocation);

      // ===== 郑甜 =====
      const ztCorruption = _.get(all_variables, 'stat_data.郑甜.堕落值', 0);
      const ztDesire = _.get(all_variables, 'stat_data.郑甜.性欲值', 0);
      const ztAction = _.get(all_variables, 'stat_data.郑甜.当前行动', '-');
      const ztOutfit = _.get(all_variables, 'stat_data.郑甜.当前穿搭', '-');
      const ztBody = _.get(all_variables, 'stat_data.郑甜.身体状况', '-');
      const ztThought = _.get(all_variables, 'stat_data.郑甜.内心想法', '-');
      const ztSex = _.get(all_variables, 'stat_data.郑甜.最近性行为', '-');
      const zt40Trigger = _.get(all_variables, 'stat_data.郑甜.堕落40触发', '未触发');
      const ztCompare = _.get(all_variables, 'stat_data.郑甜.对比做爱完成', '否');

      $('#zt-corruption-num').text(ztCorruption);
      $('#zt-corruption-fill').css('width', ztCorruption + '%');
      $('#zt-desire-num').text(ztDesire);
      $('#zt-desire-fill').css('width', ztDesire + '%');
      $('#zt-action').text(ztAction);
      $('#zt-outfit').text(ztOutfit);
      $('#zt-body').text(ztBody);
      $('#zt-thought').text(ztThought);
      $('#zt-sex').text(ztSex);

