      $('#zt-event-40').removeClass('done pending').addClass(zt40Trigger === '已触发' ? 'done' : 'pending');
      $('#zt-event-40 span').text(zt40Trigger);
      $('#zt-event-compare').removeClass('done pending').addClass(ztCompare === '是' ? 'done' : 'pending');
      $('#zt-event-compare span').text(ztCompare === '是' ? '已完成' : '未完成');

      // ===== 周彦（独立根级对象） =====
      const zySuspicion = _.get(all_variables, 'stat_data.周彦.怀疑值', 0);
