      $('#jyy-outfit').text(jyyOutfit);

      // ===== 许晴柔 =====
      const xqrFavor = _.get(all_variables, 'stat_data.许晴柔.好感度', 0);
      const xqrAction = _.get(all_variables, 'stat_data.许晴柔.当前行动', '-');
      const xqrThought = _.get(all_variables, 'stat_data.许晴柔.内心想法', '-');
      const xqrOutfit = _.get(all_variables, 'stat_data.许晴柔.当前穿搭', '-');

      $('#xqr-favor-num').text(xqrFavor);
      $('#xqr-favor-fill').css('width', xqrFavor + '%');
      $('#xqr-action').text(xqrAction);
      $('#xqr-thought').text(xqrThought);
      $('#xqr-outfit').text(xqrOutfit);

      // ===== 可触发事件（根级变量，带前缀） =====
      const hotspringStatus = _.get(all_variables, 'stat_data.事件_温泉旅行', '🔒 需要堕落值30解锁');
      const beachStatus = _.get(all_variables, 'stat_data.事件_海边出游', '🔒 需要堕落值45解锁');
      const campStatus = _.get(all_variables, 'stat_data.事件_露营过夜', '🔒 需要堕落值60解锁');

      const hotspringUnlocked = hotspringStatus.includes('✅');
      const beachUnlocked = beachStatus.includes('✅');
      const campUnlocked = campStatus.includes('✅');

      $('#event-hotspring').removeClass('locked unlocked').addClass(hotspringUnlocked ? 'unlocked' : 'locked');
      $('#event-hotspring-status').text(hotspringStatus);
      $('#event-beach').removeClass('locked unlocked').addClass(beachUnlocked ? 'unlocked' : 'locked');
      $('#event-beach-status').text(beachStatus);
      $('#event-camp').removeClass('locked unlocked').addClass(campUnlocked ? 'unlocked' : 'locked');
      $('#event-camp-status').text(campStatus);
    }

    async function init() {
      await waitGlobalInitialized('Mvu');
      populateCharacterData();

      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
        populateCharacterData();
      });

      // 角色卡片折叠
      $('.char-header').on('click', function() {
        $(this).toggleClass('collapsed');
        $(this).next('.char-detail').toggleClass('hidden');
      });

      $('.char-header').addClass('collapsed');
      $('.char-detail').addClass('hidden');

      // 其他角色区域折叠
      $('.others-header').on('click', function() {
        $(this).toggleClass('collapsed');
        $(this).next('.others-list').toggleClass('hidden');
      });

      $('.others-header').addClass('collapsed');
      $('.others-list').addClass('hidden');

      // 事件区域折叠
      $('.events-header').on('click', function() {
        $(this).toggleClass('collapsed');
        $(this).next('.events-list').toggleClass('hidden');
      });

      $('.events-header').addClass('collapsed');
      $('.events-list').addClass('hidden');

      // 主题切换
      $('#theme-btn').on('click', function() {
        if ($('body').hasClass('night')) {
          $('body').removeClass('night').addClass('day');
          $(this).html('☀️');
        } else {
          $('body').removeClass('day').addClass('night');
          $(this).html('🌙');
        }
      });
    }

    $(errorCatched(init));
  </script>
</head>
